// Pseudocode: simplified candidate lookup + offer flow
func HandleRequest(req RideRequest) {
  // route to owning Dispatch node (Ringpop does this)
  shard := ringpop.LookupShard(req.Location)
  candidates := shard.GeoIndex.Nearby(req.Location, MaxCandidates)

  // parallel enrichment (pricing/ETA) without blocking selection
  enriched := parallel.Enrich(candidates, func(c Candidate) Candidate {
    c.Price = PricingService.Estimate(req, c)
    c.ETA = ETACalc(req, c)
    return c
  })

  // prioritize and offer
  sorted := prioritize(enriched)
  for _, c := range sorted {
    if OfferService.TrySendOffer(c.DriverID, req) {
      recordMatch(req, c)
      break
    }
  }
}
